class MyClass {
public:
  static constexpr double pi = 3.14159;
  static constexpr int square(int x) noexcept { return x * x; }
  constexpr double calculate(double radius) const noexcept {
    return pi * square(radius); // Compile-time evaluation if 'radius' is known at compile time
  }
};

int main() {
  constexpr int size = MyClass::square(5); // Compile-time calculation of array size
  double result = MyClass().calculate(2.0); // May be compile-time or runtime evaluation depending on compiler optimization
  constexpr double result2 = MyClass().calculate(2.0); // Compiler error if calculate() can't be evaluated at compile-time
  double arr[size]; // Array size determined at compile-time
}
